#!/usr/bin/env python3
"""Underline all headline paragraphs in the unpacked quarterly report document.

Headlines are the report's section-title paragraphs (all-caps text); body
paragraphs, bullets, and table rows contain lowercase text. For each headline
run, add <w:u w:val="single"/> to its w:rPr in schema-correct position.
"""
import sys
import xml.dom.minidom as minidom
from pathlib import Path

doc_path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("unpacked/word/document.xml")
dom = minidom.parse(str(doc_path))

RPR_ORDER = [
    "rStyle", "rFonts", "b", "bCs", "i", "iCs", "caps", "smallCaps", "strike",
    "dstrike", "outline", "shadow", "emboss", "imprint", "noProof", "snapToGrid",
    "vanish", "webHidden", "color", "spacing", "w", "kern", "position", "sz",
    "szCs", "highlight", "u", "effect", "bdr", "shd", "fitText", "vertAlign",
    "rtl", "cs", "em", "lang", "eastAsianLayout", "specVanish", "oMath",
]


def local(tag):
    return tag.split(":")[-1]


def paragraph_text(p):
    parts = []
    for tag in ("w:t", "w:delText"):
        for node in p.getElementsByTagName(tag):
            if node.firstChild and node.firstChild.nodeType == node.TEXT_NODE:
                parts.append(node.firstChild.data)
    return "".join(parts)


def is_headline(p):
    text = paragraph_text(p).strip()
    return bool(text) and text.isupper() and any(c.isalpha() for c in text)


def ensure_underline(run):
    rprs = [c for c in run.childNodes
            if c.nodeType == c.ELEMENT_NODE and local(c.tagName) == "rPr"]
    if rprs:
        rpr = rprs[0]
        run.removeChild(rpr)
    else:
        rpr = dom.createElement("w:rPr")
    run.insertBefore(rpr, run.firstChild)

    for u in [c for c in rpr.childNodes
              if c.nodeType == c.ELEMENT_NODE and local(c.tagName) == "u"]:
        rpr.removeChild(u)

    u = dom.createElement("w:u")
    u.setAttribute("w:val", "single")
    u_index = RPR_ORDER.index("u")
    insert_before = None
    for c in rpr.childNodes:
        if c.nodeType != c.ELEMENT_NODE:
            continue
        name = local(c.tagName)
        idx = RPR_ORDER.index(name) if name in RPR_ORDER else len(RPR_ORDER)
        if idx > u_index:
            insert_before = c
            break
    if insert_before is not None:
        rpr.insertBefore(u, insert_before)
    else:
        rpr.appendChild(u)


headlines = []
for p in dom.getElementsByTagName("w:p"):
    if is_headline(p):
        headlines.append(paragraph_text(p).strip())
        for run in p.getElementsByTagName("w:r"):
            ensure_underline(run)

with open(doc_path, "wb") as f:
    f.write(dom.toxml(encoding="UTF-8"))

print(f"Underlined {len(headlines)} headlines:")
for h in headlines:
    print(" -", h)

#!/usr/bin/env python3
"""Standard-library equivalent of the docx skill's pack.py.

Condenses pretty-printed XML (preserving text content of w:t-like elements)
and packs the directory back into quarterly_report.docx.
"""
import sys
import zipfile
import xml.dom.minidom as minidom
from pathlib import Path

input_dir, output_file = sys.argv[1], sys.argv[2]
src = Path(input_dir)
out = Path(output_file)

TEXT_TAGS = {"t", "delText", "instrText"}


def local(tag):
    return tag.split(":")[-1]


def condense(dom):
    for element in dom.getElementsByTagName("*"):
        if local(element.tagName) in TEXT_TAGS:
            continue
        for child in list(element.childNodes):
            if child.nodeType == child.COMMENT_NODE:
                element.removeChild(child)
            elif (child.nodeType == child.TEXT_NODE
                  and child.data and not child.data.strip()):
                element.removeChild(child)
    return dom


for xml_file in list(src.rglob("*.xml")) + list(src.rglob("*.rels")):
    dom = condense(minidom.parse(str(xml_file)))
    xml_file.write_bytes(dom.toxml(encoding="UTF-8"))

out.parent.mkdir(parents=True, exist_ok=True)
with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as zf:
    for f in sorted(src.rglob("*")):
        if f.is_file():
            zf.write(f, f.relative_to(src))
            print("adding", f.relative_to(src))

print("packed ->", out)

