import sys
import zipfile
import xml.dom.minidom as minidom

docx_path = sys.argv[1] if len(sys.argv) > 1 else "quarterly_report.docx"
original_path = sys.argv[2] if len(sys.argv) > 2 else "unpacked/word/document.xml"

with zipfile.ZipFile(docx_path) as zf:
    dom = minidom.parseString(zf.read("word/document.xml"))
orig_dom = minidom.parse(original_path)


def local(tag):
    return tag.split(":")[-1]


def para_text(p):
    parts = []
    for tag in ("w:t", "w:delText"):
        for node in p.getElementsByTagName(tag):
            if node.firstChild and node.firstChild.nodeType == node.TEXT_NODE:
                parts.append(node.firstChild.data)
    return "".join(parts)


def para_underlined(p):
    for run in p.getElementsByTagName("w:r"):
        for rpr in run.getElementsByTagName("w:rPr"):
            for u in rpr.getElementsByTagName("w:u"):
                if u.getAttribute("w:val") == "single":
                    return True
    return False


orig_texts = [para_text(p).strip() for p in orig_dom.getElementsByTagName("w:p")]
new_texts = [para_text(p).strip() for p in dom.getElementsByTagName("w:p")]
assert orig_texts == new_texts, "TEXT CHANGED: document content does not match original"

headlines, underlined, others = [], [], []
for p in dom.getElementsByTagName("w:p"):
    t = para_text(p).strip()
    if not t:
        continue
    if para_underlined(p):
        underlined.append(t)
    else:
        others.append(t)

print(f"Underlined paragraphs ({len(underlined)}):")
for t in underlined:
    print("  [U]", t)
print(f"Non-underlined non-empty paragraphs ({len(others)}):")
for t in others:
    print("  [ ]", t)
print(f"Text content identical to original: {orig_texts == new_texts}")

